begin;
create table public.catalog_cp_aliases (
 work_key text not null references public.catalog_works(work_key),
 name text not null,character_names text[] not null check(cardinality(character_names)=2),
 kind text not null default 'cp' check(kind in ('cp','combination')),
 reference_urls text[] not null check(cardinality(reference_urls)>0),
 verified_on date not null,primary key(work_key,name)
);
alter table public.catalog_cp_aliases enable row level security;
revoke all on public.catalog_cp_aliases from public,anon,authenticated;
grant select on public.catalog_cp_aliases to anon,authenticated;
create policy cp_catalog_read on public.catalog_cp_aliases for select to anon,authenticated using(true);
