insert into public.catalog_cp_aliases(work_key,name,character_names,kind,reference_urls,verified_on) select w.work_key,x.name,array(select jsonb_array_elements_text(x.characters)),x.kind,array(select jsonb_array_elements_text(x.sources)),x.verified_on from source x join public.catalog_works w on w.name=x.work;

-- Register reviewed constituent names so they can be selected in the existing interest picker.
insert into public.catalog_characters(work_key,name,aliases,active,sort_rank)
 select distinct cp.work_key,c,array[c],true,900 from public.catalog_cp_aliases cp cross join lateral unnest(cp.character_names) c
 on conflict(work_key,name) do nothing;
-- Only discovery imports are enriched. Creator ownership and explicit edits are left intact.
create function private.apply_discovery_cp() returns trigger language plpgsql set search_path='' as $$
declare chars text[];
begin
 if new.source_kind<>'x_discovery' then return new;end if;
 select array_agg(distinct c) into chars from public.catalog_cp_aliases cp
 join public.catalog_works w on w.work_key=cp.work_key cross join lateral unnest(cp.character_names) c
 where w.name=new.work_name and (coalesce(new.title,'')||' '||coalesce(new.sale_info,'')) ~* ('(^|[^[:alnum:]_])'||cp.name||'($|[^[:alnum:]_])');
 if chars is not null then new.character_names:=array(select distinct unnest(coalesce(new.character_names,'{}'::text[])||chars));end if;
 return new;
end $$;
create trigger discovery_cp_tags before insert or update of title,sale_info,work_name on public.goods_posts for each row execute function private.apply_discovery_cp();
update public.goods_posts set title=title where source_kind='x_discovery';
do $$begin assert (select count(*)=70 from public.catalog_cp_aliases),'CP seed count mismatch';end$$;
notify pgrst,'reload schema';
commit;
